CREATE function [dbo].[uspGetItemAvgRateFuncStock] ( @StoreId int,@ItemId  int, @DateFrom datetime, @DateTo datetime, @ByDate bit ) returns decimal(18,2) as Begin Declare @Amount decimal(18,2); set @Amount =0; Declare @Qty decimal(18,2); set @Qty =0; Declare @AvgRate decimal(18,2); set @AvgRate =0; if @ByDate = 0 begin  if @StoreId=0 begin select @AvgRate = (select(CAST(sum(Amount) / sum(Qty)as decimal(10,2))) from Warehouse_store where itemid = @ItemId and [type] = 'in' and date between @DateFrom and @DateTo) end  if @AvgRate = 0 begin select @AvgRate = (select Avgrate from avgratedetail where id = (select max(id)from avgratedetail where itemid = @ItemId)) end else  begin select @AvgRate = (select(CAST(sum(Amount) / sum(Qty)as decimal(10,2))) from Warehouse_store where itemid = @ItemId and [type] = 'in' and sid=@StoreId and date between @DateFrom and @DateTo) end  if @AvgRate = 0 begin select @AvgRate = (select Avgrate from avgratedetail where id = (select max(id)from avgratedetail where itemid = @ItemId)) end End else if @ByDate = 1 begin  begin select @AvgRate = (select(CAST(sum(Amount) / sum(Qty)as decimal(10,2))) from Warehouse_store where itemid = @ItemId and [type] = 'in' and date between @DateFrom and @DateTo) End if @AvgRate = 0  begin select @AvgRate = (select Avgrate from avgratedetail where id =  (select max(id)from avgratedetail where itemid = @ItemId)) end  else begin select  @AvgRate=(select(CAST(sum(Amount) / sum(Qty)as decimal(10,2))) from Warehouse_store  where itemid = @ItemId and [type] = 'in' and date between @DateFrom and @DateTo and sid=@StoreId) end  if @AvgRate = 0  begin select @AvgRate = (select Avgrate from avgratedetail where id =(select max(id)from avgratedetail where itemid = @ItemId)) end  End return @AvgRate End